#!/usr/bin/env python3
"""Autonomous Notion Tool — Generated by NEVEA Tool Creator."""
import sys
import os
import json

try:
    import requests
except ImportError:
    requests = None

def execute(params: dict) -> dict:
    title = params.get("title", "New Page from NEVEA")
    content = params.get("content", "Autonomous content synthesized by NEVEA AI Swarm.")
    parent_id = params.get("parent_id", "")
    
    token = os.environ.get("NOTION_API_KEY")
    if not token:
        vault_path = os.path.join(os.path.dirname(__file__), "..", "vault.json")
        if os.path.isfile(vault_path):
            with open(vault_path, "r", encoding="utf-8") as f:
                vdata = json.load(f)
                token = vdata.get("credentials", {}).get("NOTION_API_KEY") or vdata.get("custom_services", {}).get("NOTION_API_KEY", "")
                
    if not token:
        return {"success": False, "error": "No NOTION_API_KEY found in Universal Vault. Please add it in ModelHub."}

    if requests is None:
        return {"success": True, "simulated": True, "message": f"[Simulated Notion] Page '{title}' created."}

    headers = {
        "Authorization": f"Bearer {token}",
        "Notion-Version": "2022-06-28",
        "Content-Type": "application/json"
    }
    payload = {
        "parent": {"database_id": parent_id} if parent_id else {"page_id": "root"},
        "properties": {"title": [{"text": {"content": title}}]}
    }
    try:
        res = requests.post("https://api.notion.com/v1/pages", json=payload, headers=headers, timeout=10)
        return res.json()
    except Exception as e:
        return {"success": False, "error": str(e)}

if __name__ == "__main__":
    raw = sys.argv[1] if len(sys.argv) > 1 else "{}"
    try:
        p = json.loads(raw)
    except:
        p = {}
    print(json.dumps(execute(p)))
